    private static ManuallyDefinedAsset CreateBuild(string name, string assetPath, string iconAssetPath) => new()
    {
        Name = name,
        AssetPath = $"{assetPath}.{assetPath[(assetPath.LastIndexOf('/') + 1)..]}_C",
        IconAssetPath = iconAssetPath
    };

    private static ManuallyDefinedAsset CreateMesh(string name, string assetPath, string iconAssetPath) => new()
    {
        Name = name,
        AssetPath = assetPath,
        IconAssetPath = iconAssetPath
    };
